func (d *refCreateDenier) hook(req *packp.UpdateRequests, _ bool) *packp.ReportStatus {
	carriesRef := false
	for _, cmd := range req.Commands {
		if cmd.Name == d.ref {
			carriesRef = true
		}
	}
	if d.off || !carriesRef {
		return nil // ordinary checkpoint and delete pushes apply normally
	}
