				status = err.Error()
			}
		default:
			if err := d.repo.Storer.SetReference(plumbing.NewHashReference(cmd.Name, cmd.New)); err != nil {
				status = err.Error()
			}
		}
		report.CommandStatuses = append(report.CommandStatuses, &packp.CommandStatus{
			ReferenceName: cmd.Name,
			Status:        status,
		})
	}
	return report
}

