			return reason, ok
		},
	}
}

// A refused branch create must leave the marker in place AND leave its hash
// usable as a fetch have for the branches planned after it — the reason the
// cutover records the temp ref instead of the branch it could not create.
func TestExecuteBatchedRefusedCreateKeepsMarkerAsHave(t *testing.T) {
	trunkRef := plumbing.NewBranchReferenceName("main")
	secondRef := plumbing.NewBranchReferenceName("release")
	hashes := makeLinearCommitChain(t, 4)
	trunkHash, secondHash := hashes[3], hashes[2]
	trunkTempRef := planner.BootstrapTempRef(trunkRef)

	var (
		fetchHaves          []map[plumbing.ReferenceName]plumbing.Hash
		pushCommandsBatches [][]gitproto.PushCommand
	)
	p := batchedRefusalParams(t, trunkRef, secondRef, trunkHash, secondHash, 4,
		map[plumbing.ReferenceName]string{trunkRef: "deny creating a protected branch"},
		&fetchHaves, &pushCommandsBatches)

	if _, err := Execute(context.Background(), p, "empty target"); err != nil {
		t.Fatalf("Execute: %v", err)
	}

	for _, cmds := range pushCommandsBatches {
		for _, cmd := range cmds {
			if cmd.Name == trunkTempRef && cmd.Delete {
				t.Errorf("deleted resume marker %s after a create the target refused: %+v", trunkTempRef, cmd)
			}
		}
	}
	// The second branch's fetch must offer the kept marker's hash, or the
	// objects trunk already delivered are re-sent.
	var offeredTrunkHash bool
	for _, haves := range fetchHaves[1:] {
		if haves[trunkTempRef] == trunkHash {
			offeredTrunkHash = true
		}
	}
	if !offeredTrunkHash {
		t.Errorf("later fetch did not offer the kept marker at %s as a have: %v",
			planner.ShortHash(trunkHash), fetchHaves)
	}
}

