func TestExecuteBatchedConcurrentMoveDeletesMarker(t *testing.T) {
	trunkRef := plumbing.NewBranchReferenceName("main")
	secondRef := plumbing.NewBranchReferenceName("release")
	hashes := makeLinearCommitChain(t, 4)
	trunkTempRef := planner.BootstrapTempRef(trunkRef)

