		map[plumbing.ReferenceName]string{trunkRef: "already exists"},
		&fetchHaves, &pushCommandsBatches)

	if _, err := Execute(context.Background(), p, "empty target"); err != nil {
		t.Fatalf("Execute: %v", err)
	}

	var deletedMarker bool
	for _, cmds := range pushCommandsBatches {
		for _, cmd := range cmds {
			if cmd.Name == trunkTempRef && cmd.Delete {
				deletedMarker = true
			}
		}
	}
	if !deletedMarker {
